/**
 * Image path map for the Lumière Parfums storefront.
 *
 * Product photos live in `static/images/` as `.webp` files, generated by
 * the images agent. This map is the single place that names them, so a
 * missing file shows up here first.
 */

import { products } from './data/products';

/** All product image paths, keyed by product slug. */
export const productImages: Record<string, string> = Object.fromEntries(
	products.map((p) => [p.slug, p.image])
);

/** Hero / supporting imagery — only files that actually exist in
 *  `static/images/` (generated by the images agent). */
export const heroImages = {
	hero: '/images/hero-eclat-noir.webp',
	discoverySet: '/images/discovery-set.webp',
	giftBox: '/images/gift-box.webp',
	journalAtelier: '/images/journal-atelier.webp',
	journalIngredients: '/images/journal-ingredients.webp'
} as const;

/** Resolve a product image path by slug, falling back to the hero image. */
export function imageFor(slug: string): string {
	return productImages[slug] ?? heroImages.hero;
}
